```typescript
function abbreviateProduct(left: number, right: number): string {
    let prod: bigint = BigInt(1);
    for (let i = left; i <= right; i++) {
        prod *= BigInt(i);
    }

    const s = prod.toString();
    let c = 0;
    let idx = s.length - 1;
    while (idx >= 0 && s[idx] === '0') {
        c++;
        idx--;
    }

    const q = s.substring(0, idx + 1);
    if (q.length > 10) {
        return q.substring(0, 5) + "..." + q.substring(q.length - 5) + "e" + c;
    } else {
        return q + "e" + c;
    }
}
```

