function ambiguousCoordinates(s: string): string[] {
    const digits = s.slice(1, -1);
    const result: string[] = [];

    function getValidRepresentations(num: string): string[] {
        const reps: string[] = [];
        const n = num.length;

        // Integer representation
        if (n === 1 || num[0] !== '0') {
            reps.push(num);
        }

        // Decimal representation
        for (let i = 1; i < n; i++) {
            const left = num.slice(0, i);
            const right = num.slice(i);

            // Integer part cannot have leading zeros unless it is exactly "0"
            if (left.length > 1 && left[0] === '0') {
                continue;
            }

            // Fractional part cannot end with zero
            if (right.endsWith('0')) {
                continue;
            }

            reps.push(left + '.' + right);
        }

        return reps;
    }

    for (let i = 1; i < digits.length; i++) {
        const leftPart = digits.slice(0, i);
        const rightPart = digits.slice(i);

        const leftReps = getValidRepresentations(leftPart);
        const rightReps = getValidRepresentations(rightPart);

        for (const left of leftReps) {
            for (const right of rightReps) {
                result.push(`(${left}, ${right})`);
            }
        }
    }

    return result;
}
```

