function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    const roof = total;
    const parent = new Array(total + 1);
    const size = new Array(total + 1).fill(0);
    for (let i = 0; i <= total; i++) parent[i] = i;

    const hitBrick: boolean[] = new Array(hits.length).fill(false);
    // Remove hit bricks
    for (let i = 0; i < hits.length; i++) {
        const [r, c] = hits[i];
        if (grid[r][c] === 1) {
            hitBrick[i] = true;
            grid[r][c] = 0;
        }
    }

    const idx = (r: number, c: number) => r * n + c;

    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a: number, b: number) => {
        let ra = find(a);
        let rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) {
            const tmp = ra; ra = rb; rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    };

    // Initialize remaining bricks
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                size[idx(r,c)] = 1;
            }
        }
    }

    // Build components
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== 1) continue;
            const id = idx(r,c);
            if (r === 0) union(id, roof);
            if (r + 1 < m && grid[r+1][c] === 1) union(id, idx(r+1, c));
            if (c + 1 < n && grid[r][c+1] === 1) union(id, idx(r, c+1));
        }
    }

    const ans: number[] = new Array(hits.length).fill(0);
    const dirs = [[-1,0],[0,-1],[1,0],[0,1]];

    for (let i = hits.length - 1; i >= 0; i--) {
        if (!hitBrick[i]) {
            ans[i] = 0;
            continue;
        }
        const [r, c] = hits[i];
        const oldSize = size[find(roof)];
        grid[r][c] = 1;
        const id = idx(r,c);
        parent[id] = id;
        size[id] = 1;

        if (r === 0) union(id, roof);
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {
                union(id, idx(nr, nc));
            }
        }

        const newSize = size[find(roof)];
        ans[i] = newSize - oldSize - 1;
    }

    return ans;
}
