function evaluate(s: string, knowledge: string[][]): string {
    const map = new Map<string, string>();
    for (const [key, value] of knowledge) {
        map.set(key, value);
    }

    const result: string[] = [];
    let i = 0;
    const n = s.length;

    while (i < n) {
        const ch = s[i];
        if (ch === '(') {
            const close = s.indexOf(')', i + 1);
            const key = s.substring(i + 1, close);
            const value = map.get(key);
            result.push(value !== undefined ? value : '?');
            i = close + 1;
        } else {
            result.push(ch);
            i++;
        }
    }

    return result.join('');
}
