        this.maxVal = 100000;
        this.bitCount = new Array(this.maxVal + 2).fill(0);
        this.bitSum = new Array(this.maxVal + 2).fill(0);
        this.stream = [];
        this.head = 0;
    }

    private fenwickAdd(index: number, deltaCount: number, deltaSum: number): void {
        for (let i = index; i <= this.maxVal; i += i & -i) {
            this.bitCount[i] += deltaCount;
            this.bitSum[i] += deltaSum;
        }
    }

