        let result = 0;
        for (let i = index; i > 0; i -= i & -i) {
            result += this.bitCount[i];
        }
        return result;
    }

    private prefixSum(index: number): number {
        let result = 0;
        for (let i = index; i > 0; i -= i & -i) {
            result += this.bitSum[i];
        }
        return result;
    }

