function canCross(stones: number[]): boolean {
  const n=stones.length;
  const posToIndex = new Map<number, number>();
  for(let i=0;i<n;i++) posToIndex.set(stones[i],i);
  const dp: Set<number>[] = Array.from({length:n},()=>new Set<number>());
  dp[0].add(0);
  for(let i=0;i<n;i++){
    const pos = stones[i];
    for (const k of dp[i]) {
      for (let step = k-1; step <= k+1; step++) {
        if (step <= 0) continue;
        const nextPos = pos + step;
        const nextIndex = posToIndex.get(nextPos);
        if (nextIndex !== undefined) {
          dp[nextIndex].add(step);
        }
      }
    }
  }
  return dp[n-1].size > 0;
}

