function maxScore(nums: number[]): number {
    const m = nums.length;
    const totalMasks = 1 << m;
    const dp = new Array<number>(totalMasks).fill(-1);
    dp[0] = 0;

    function gcd(a: number, b: number): number {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    const bitCount = (x: number): number => {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    };

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dp[mask] < 0) continue;
        const op = bitCount(mask) / 2 + 1;
        if (op > m / 2) continue;
        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;
            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;
                const next = mask | (1 << i) | (1 << j);
                const score = dp[mask] + op * gcd(nums[i], nums[j]);
                if (score > dp[next]) dp[next] = score;
            }
        }
    }

    return dp[totalMasks - 1];
}
