function maximumANDSum(nums: number[], numSlots: number): number {
    const n = nums.length;
    const pow3: number[] = [1];

    for (let i = 1; i < numSlots; i++) {
        pow3[i] = pow3[i - 1] * 3;
    }

    const totalStates = pow3[numSlots - 1] * 3;
    const dp = new Int32Array(totalStates);
    dp.fill(-1);
    dp[0] = 0;

    let answer = 0;

    for (let mask = 0; mask < totalStates; mask++) {
        const current = dp[mask];
        if (current < 0) continue;

        let k = 0;
        let temp = mask;
        for (let i = 0; i < numSlots; i++) {
            k += temp % 3;
            temp = Math.floor(temp / 3);
        }

        if (k >= n) {
            if (k === n && current > answer) {
                answer = current;
            }
            continue;
        }

        const value = nums[k];

        for (let i = 0; i < numSlots; i++) {
            const digit = Math.floor(mask / pow3[i]) % 3;

            if (digit < 2) {
                const nextMask = mask + pow3[i];
                const nextValue = current + (value & (i + 1));

                if (nextValue > dp[nextMask]) {
                    dp[nextMask] = nextValue;
                }
            }
        }
    }

    return answer;
}
