```typescript
function maxCompatibilitySum(students: number[][], mentors: number[][]): number {
    const m = students.length;
    const n = students[0].length;

    const score: number[][] = Array.from({ length: m }, () => Array(m).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) {
                    s++;
                }
            }
            score[i][j] = s;
        }
    }

    const totalMasks = 1 << m;
    const dp: number[] = Array(totalMasks).fill(-1);
    dp[0] = 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        if (dp[mask] === -1) continue;

        let studentIndex = 0;
        let temp = mask;
        while (temp > 0) {
            studentIndex += temp & 1;
            temp >>= 1;
        }

        if (studentIndex >= m) continue;

        for (let mentorIndex = 0; mentorIndex < m; mentorIndex++) {
            if ((mask & (1 << mentorIndex)) === 0) {
                const nextMask = mask | (1 << mentorIndex);
                const nextScore = dp[mask] + score[studentIndex][mentorIndex];
                if (nextScore > dp[nextMask]) {
                    dp[nextMask] = nextScore;
                }
            }
        }
    }

    return dp[totalMasks - 1];
}
```

