function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
    let left = 0;
    let sum = 0;
    let ans = 0;

    for (let right = 0; right < fruits.length; right++) {
        sum += fruits[right][1];

        while (left <= right) {
            const L = fruits[left][0];
            const R = fruits[right][0];
            const steps = (R - L) + Math.min(
                Math.abs(startPos - L),
                Math.abs(startPos - R)
            );

            if (steps <= k) break;

            sum -= fruits[left][1];
            left++;
        }

        if (sum > ans) ans = sum;
    }

    return ans;
}
```

