function maxRunTime(n: number, batteries: number[]): number {
    let sum = 0;
    for (const b of batteries) {
        sum += b;
    }

    let left = 0;
    let right = Math.floor(sum / n);

    while (left < right) {
        const mid = Math.floor((left + right + 1) / 2);
        let available = 0;

        for (const b of batteries) {
            available += Math.min(b, mid);
        }

        if (available >= n * mid) {
            left = mid;
        } else {
            right = mid - 1;
        }
    }

    return left;
}
