```typescript
function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;
    const full = 1 << n;

    const popcount = (x: number): number => {
        let count = 0;
        while (x > 0) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    };

    const valid: number[][] = [];

    for (let i = 0; i < m; i++) {
        const rowValid: number[] = [];

        for (let mask = 0; mask < full; mask++) {
            if ((mask & (mask << 1)) !== 0) continue;

            let ok = true;
            for (let j = 0; j < n; j++) {
                if ((mask & (1 << j)) !== 0 && seats[i][j] !== '.') {
                    ok = false;
                    break;
                }
            }

            if (ok) rowValid.push(mask);
        }

        valid.push(rowValid);
    }

    let dp = new Map<number, number>();

    for (const mask of valid[0]) {
        dp.set(mask, popcount(mask));
    }

    for (let i = 1; i < m; i++) {
        const nextDp = new Map<number, number>();

        for (const cur of valid[i]) {
            let best = -1;

            for (const prev of valid[i - 1]) {
                if (!dp.has(prev)) continue;

                if ((cur & (prev << 1)) === 0 && (cur & (prev >> 1)) === 0) {
                    best = Math.max(best, dp.get(prev)! + popcount(cur));
                }
            }

            if (best >= 0) {
                nextDp.set(cur, best);
            }
        }

        dp = nextDp;
    }

    let answer = 0;
    for (const value of dp.values()) {
        answer = Math.max(answer, value);
    }

    return answer;
}
```

