```typescript
function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const prefix = new Array<number>(n + 1).fill(0);

    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    const sum = (start: number, len: number): number => {
        return prefix[start + len] - prefix[start];
    };

    let maxSum = 0;

    for (let i = 0; i + firstLen <= n; i++) {
        const firstSum = sum(i, firstLen);

        for (let j = 0; j + secondLen <= n; j++) {
            if (i + firstLen <= j || j + secondLen <= i) {
                maxSum = Math.max(maxSum, firstSum + sum(j, secondLen));
            }
        }
    }

    return maxSum;
}
```

