function minCost(maxTime: number, edges: number[][], passingFees: number[]): number {
    const n = passingFees.length;
    const INF = Number.MAX_SAFE_INTEGER / 2;
    const dp: number[][] = Array.from({ length: maxTime + 1 }, () => new Array(n).fill(INF));

    dp[0][0] = passingFees[0];

    for (let t = 0; t <= maxTime; t++) {
        const row = dp[t];

        for (const [u, v, w] of edges) {
            const nextTime = t + w;
            if (nextTime > maxTime) continue;

            if (row[u] < INF) {
                const cost = row[u] + passingFees[v];
                if (cost < dp[nextTime][v]) {
                    dp[nextTime][v] = cost;
                }
            }

            if (row[v] < INF) {
                const cost = row[v] + passingFees[u];
                if (cost < dp[nextTime][u]) {
                    dp[nextTime][u] = cost;
                }
            }
        }
    }

    let answer = INF;
    for (let t = 0; t <= maxTime; t++) {
        if (dp[t][n - 1] < answer) {
            answer = dp[t][n - 1];
        }
    }

    return answer >= INF ? -1 : answer;
}
