function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const total = 1 << n;
    const sessions = new Array(total).fill(Infinity);
    const remaining = new Array(total).fill(-1);
    sessions[0] = 0;
    remaining[0] = 0; // no open session, but remaining 0
    for (let mask = 0; mask < total; mask++) {
        if (sessions[mask] === Infinity) continue;
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const next = mask | (1 << i);
            let ns = sessions[mask];
            let nr = remaining[mask];
            if (nr >= tasks[i]) {
                nr -= tasks[i];
            } else {
                ns += 1;
                nr = sessionTime - tasks[i];
            }
            // Better: fewer sessions, or same sessions and larger remaining
            if (ns < sessions[next] || (ns === sessions[next] && nr > remaining[next])) {
                sessions[next] = ns;
                remaining[next] = nr;
            }
        }
    }
