function nextGreaterElements(nums: number[]): number[] {
    const n = nums.length;
    const res: number[] = new Array(n).fill(-1);
    const stack: number[] = [];

    for (let i = 2 * n - 1; i >= 0; i--) {
        const idx = i % n;
        const val = nums[idx];

        while (stack.length > 0 && stack[stack.length - 1] <= val) {
