        if (!dp[mask]) continue;

        const remainder = sum[mask] % target;

        for (let i = 0; i < n; i++) {
            const bit = 1 << i;
            if ((mask & bit) !== 0) continue;

            if (remainder + nums[i] <= target) {
                dp[mask | bit] = true;
            }
        }
    }

    return dp[N - 1];
}
