function maxSizeSlices(slices: number[]): number {
    const m = slices.length;
    const n = Math.floor(m / 3);

    const solve = (arr: number[]): number => {
        const len = arr.length;
        const dp: number[][] = Array.from({ length: len + 1 }, () =>
            Array(n + 1).fill(-Infinity)
        );

        dp[0][0] = 0;

        for (let i = 1; i <= len; i++) {
            dp[i][0] = 0;
            const maxJ = Math.min(n, Math.floor((i + 1) / 2));

            for (let j = 1; j <= maxJ; j++) {
                dp[i][j] = dp[i - 1][j];

                if (i === 1) {
                    if (j === 1) {
                        dp[i][j] = Math.max(dp[i][j], arr[0]);
