                    const prev = dp[i - 2][j - 1];
                    if (prev !== -Infinity) {
                        dp[i][j] = Math.max(dp[i][j], prev + arr[i - 1]);
                    }
                }
            }
        }

        return dp[len][n];
    };

    return Math.max(
        solve(slices.slice(0, m - 1)),
        solve(slices.slice(1))
    );
}
```

