```typescript
function isScramble(s1: string, s2: string): boolean {
    const memo = new Map<string, boolean>();

    function dfs(a: string, b: string): boolean {
        if (a === b) return true;
        if (a.length !== b.length) return false;

        const key = `${a}#${b}`;
        const cached = memo.get(key);
        if (cached !== undefined) return cached;

        const n = a.length;
        const count = new Array(26).fill(0);

        for (let i = 0; i < n; i++) {
            count[a.charCodeAt(i) - 97]++;
            count[b.charCodeAt(i) - 97]--;
        }

        for (let i = 0; i < 26; i++) {
            if (count[i] !== 0) {
                memo.set(key, false);
                return false;
            }
        }

        for (let k = 1; k < n; k++) {
            if (
                dfs(a.slice(0, k), b.slice(0, k)) &&
                dfs(a.slice(k), b.slice(k))
            ) {
                memo.set(key, true);
                return true;
            }

            if (
                dfs(a.slice(0, k), b.slice(n - k)) &&
                dfs(a.slice(k), b.slice(0, n - k))
            ) {
                memo.set(key, true);
                return true;
            }
        }

        memo.set(key, false);
        return false;
    }

    return dfs(s1, s2);
}
```

