function shiftGrid(grid: number[][], k: number): number[][] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    const flat: number[] = [];

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            flat.push(grid[i][j]);
        }
    }

    const shift = k % total;
    const result: number[][] = Array.from({ length: m }, () => Array(n).fill(0));

    for (let i = 0; i < total; i++) {
        const newIndex = (i + shift) % total;
        const row = Math.floor(newIndex / n);
        const col = newIndex % n;
        result[row][col] = flat[i];
    }

    return result;
}
