function sortByBits(arr: number[]): number[] {
    const countBits = (n: number): number => {
        let count = 0;
        while (n > 0) {
            count += n & 1;
            n >>= 1;
        }
        return count;
    };

    return arr.sort((a, b) => {
        const countA = countBits(a);
        const countB = countBits(b);
        if (countA !== countB) {
            return countA - countB;
        }
        return a - b;
    });
}
