function splitArray(nums: number[], k: number): number {
    let lo = Math.max(...nums);
    let hi = nums.reduce((a,b)=>a+b,0);
    const canSplit = (limit: number): boolean => {
        let count = 1;
        let cur = 0;
        for (const x of nums) {
            if (cur + x > limit) {
                count++;
                cur = x;
            } else {
                cur += x;
            }
        }
        return count <= k;
    };
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (canSplit(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
