        this.buffer = "";

        for (const word of words) {
            this.maxLen = Math.max(this.maxLen, word.length);

            let node = this.root;
            for (let i = word.length - 1; i >= 0; i--) {
                const ch = word[i];
                if (!node.children[ch]) {
                    node.children[ch] = { children: {}, isEnd: false };
                }
                node = node.children[ch];
            }
            node.isEnd = true;
        }
