```typescript
function validateBinaryTreeNodes(n: number, leftChild: number[], rightChild: number[]): boolean {
    const indegree = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        const left = leftChild[i];
        const right = rightChild[i];

        if (left !== -1) {
            indegree[left]++;
            if (indegree[left] > 1) return false;
        }

        if (right !== -1) {
            indegree[right]++;
            if (indegree[right] > 1) return false;
        }
    }

    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }

    if (root === -1) return false;

    const visited = new Array(n).fill(false);
    const stack: number[] = [root];
    let count = 0;

    while (stack.length > 0) {
        const node = stack.pop()!;

        if (visited[node]) continue;
        visited[node] = true;
        count++;

        const left = leftChild[node];
        const right = rightChild[node];

        if (left !== -1) stack.push(left);
        if (right !== -1) stack.push(right);
    }

    return count === n;
}
```

