    const resultCols: number[] = new Array(maxLen).fill(-1);
    const notZero: boolean[] = new Array(26).fill(false);

    for (const w of allWords) {
        if (w.length > 1) {
            notZero[w.charCodeAt(0) - 65] = true;
        }
    }

    for (let col = 0; col < maxLen; col++) {
        for (const w of words) {
            if (col < w.length) {
                const ch = w.charCodeAt(w.length - 1 - col) - 65;
                cols[col].push(ch);
            }
        }
        if (col < result.length) {
            resultCols[col] = result.charCodeAt(result.length - 1 - col) - 65;
        }
    }

    const assign: number[] = new Array(26).fill(-1);
    const used: boolean[] = new Array(10).fill(false);

    function dfs(col: number, carry: number): boolean {
        if (col === maxLen) {
            return carry === 0;
        }
        return processWord(col, 0, carry);
    }

    function processWord(col: number, idx: number, sum: number): boolean {
        const wordChars = cols[col];
        if (idx === wordChars.length) {
            const digit = sum % 10;
            const nextCarry = Math.floor(sum / 10);
            const rch = resultCols[col];

            if (rch === -1) {
                if (digit !== 0) return false;
                return dfs(col + 1, nextCarry);
            }

