                if (digit === 0 && notZero[rch]) return false;
                assign[rch] = digit;
                used[digit] = true;
                const ok = dfs(col + 1, nextCarry);
                assign[rch] = -1;
                used[digit] = false;
                return ok;
            }
        }

        const ch = wordChars[idx];
        const assigned = assign[ch];
        if (assigned !== -1) {
            return processWord(col, idx + 1, sum + assigned);
        } else {
            for (let d = 0; d <= 9; d++) {
                if (used[d]) continue;
                if (d === 0 && notZero[ch]) continue;
                assign[ch] = d;
                used[d] = true;
                if (processWord(col, idx + 1, sum + d)) return true;
